bool CBattleQuery::blocksPack(const CPackForServer * pack) const
{
	if(dynamic_cast<const MakeAction*>(pack) != nullptr)
		return false;

	if(dynamic_cast<const GamePause*>(pack) != nullptr)
		return false;

	return true;
}

bool CGameHandler::isBlockedByQueries(const CPackForServer *pack, PlayerColor player)
{
#ifdef VCMI_HTML5_BUILD
 // A quiet browser checkpoint may run while the owned-town UI is open.
 // Ongoing battles remain excluded: their query state is not serialized.
 if(const auto save=dynamic_cast<const SaveGame *>(pack))
  if((save->fname=="Saves/Goonk-auto"||save->fname=="Saves/Goonk-online-auto")&&!save->notifySuccess&&!gameState().getBattle(player))return false;
#endif

	if (dynamic_cast<const PlayerMessage *>(pack) != nullptr)
		return false;

	if (dynamic_cast<const SaveLocalState *>(pack) != nullptr)
		return false;

	auto query = queries->topQuery(player);
	if (query && query->blocksPack(pack))
	{
		complain(boost::str(boost::format(
			"\r\n| Player \"%s\" has to answer queries before attempting any further actions.\r\n| Top Query: \"%s\"\r\n")
			% boost::to_upper_copy<std::string>(player.toString())
			% query->toString()
		));
		return true;
	}

